__NUXT_JSONP__("/sp/how-to-apply/student-visa-f1", {data:[{details:{slug:"sp",pageTitle:"Estudiante VISA F1 | Mentor Language Institute",pageDescription:"Por favor, elija su situación de la lista a continuación.",title:"Estudiante VISA F1",image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fvisa_application.jpg",subtitle:["Por favor, elija su situación de la lista a continuación. \u003Cbr \u002F\u003E Si no está seguro de su situación, haga clic en LEER MÁS para obtener más detalles."],category:[{btn_visa:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas_btn_sp.png",link:"\u002Fsp\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Foverseas-students"},btn_transfer:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer_student_btn_sp.png",link:"\u002Fsp\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Ftransfer-students"},btn_status:{image:"\u002Fimages\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange_status_btn_sp.png",link:"\u002Fsp\u002Fhow-to-apply\u002Fstudent-visa-f1\u002Fchange-of-status"}}],content:{subtitle:"¿Alguna pregunta?",description:["Normalmente, necesitará una visa para permanecer como estudiante a largo plazo en los Estados Unidos. \u003Cbr \u002F\u003E Si no sabes si necesitas una visa o no, contáctenos.","Ofrecemos asistencia en 8 idiomas diferentes."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Fhow-to-apply\u002Fcontact-us-sp.jpg",link:"\u002Fsp\u002Fcontact"}},dir:"\u002Fstudent-visa-f1",path:"\u002Fstudent-visa-f1\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:31.145Z",updatedAt:"2025-05-26T12:06:27.926Z"}}],fetch:{},mutations:void 0});